-- Playback lifecycle log menu and API permissions (PostgreSQL).

SELECT COALESCE((SELECT MIN(id) FROM sys_menu WHERE path='/media' AND type IN (1,2) AND deleted_at IS NULL),0),'/gb28181/playback-log','gb28181-playback-log','gb28181/playback-log/index','播放日志',0,0,7,2,'gb28181:play-log:view','lucide:FileClock',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1
WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE path='/gb28181/playback-log' AND deleted_at IS NULL);

